-- bipar_lote_scanner: processa um lote inteiro de containers do Scanner QR numa única chamada.
-- Antes o frontend fazia ~3 round-trips por caixa (SELECT estoque + RPC bipar_etiqueta + INSERT
-- movimentacoes); esta função troca tudo por 1 chamada por lote.
--
-- Atribuicao de usuario: chama get_usuario_id_from_auth(auth.uid()) de forma INEQUIVOCA
-- (a funcao tem 2 overloads — chamar sem arg dava "function is not unique") e dentro de bloco
-- de excecao — atribuir usuario NUNCA derruba a entrada. Antes o Scanner deixava usuario_id NULL,
-- entao a coluna "Responsável" da lista ficava vazia.
--
-- QTY AUTORITATIVA: quando ha uid, a quantidade vem da propria etiqueta
-- (quantidade_disponivel; senao quantidade_interna) — a caixa sabe quantas unidades tem.
-- Garante +40 (o conteudo real), nunca +1 por payload incompleto.
--
-- Cada item e' isolado em seu proprio bloco de excecao: 1 item ruim nao derruba o lote.

CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(
    p_loja_id integer,
    p_tipo text,
    p_itens jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_usuario_id integer;
    v_item jsonb;
    v_id text;
    v_pid integer;
    v_uid text;
    v_lote_id uuid;
    v_qty numeric;
    v_disp numeric;
    v_interna numeric;
    v_tipo_embalagem text;
    v_embalagem_nome text;
    v_lote text;
    v_payload jsonb;
    v_saldo_anterior numeric;
    v_saldo_novo numeric;
    v_motivo text;
    v_observacoes text;
    v_resultados jsonb := '[]'::jsonb;
    v_ok integer := 0;
    v_err integer := 0;
BEGIN
    -- Atribuicao de usuario: chamada inequivoca (1 arg) + nunca fatal.
    BEGIN
        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
    EXCEPTION WHEN OTHERS THEN
        v_usuario_id := NULL;
    END;

    -- Itera NA ORDEM do array: o trigger AFTER INSERT em movimentacoes atualiza `estoque`,
    -- entao re-selecionar `estoque` a cada item da o saldo corrente correto na mesma transacao
    -- (varios containers do mesmo produto acumulam saldo na sequencia certa).
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
    LOOP
        v_id := v_item->>'id';
        BEGIN
            v_pid := (v_item->>'pid')::integer;
            v_uid := NULLIF(v_item->>'uid', '');
            v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
            v_qty := (v_item->>'qty')::numeric;
            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
            v_lote := NULLIF(v_item->>'lote', '');
            v_payload := v_item->'payload';

            -- Atualiza status da etiqueta (reaproveita RPC; backfill garante a linha existir).
            -- Nao mexe em estoque/movimentacoes; ok=false e' so warning; excecao nao derruba o item.
            IF v_uid IS NOT NULL THEN
                BEGIN
                    PERFORM public.bipar_etiqueta(
                        v_uid,
                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
                        jsonb_build_object(
                            'loja_id', p_loja_id,
                            'referencia_tipo', 'scanner_lote',
                            'payload', v_payload
                        )
                    );
                EXCEPTION WHEN OTHERS THEN
                    NULL;
                END;

                -- QTY AUTORITATIVA: o que a caixa realmente tem (disponivel), senao capacidade
                -- nominal (interna), senao o que o front mandou. Evita o bug de "+1".
                SELECT quantidade_disponivel, quantidade_interna
                  INTO v_disp, v_interna
                  FROM etiquetas_qr
                 WHERE uid = v_uid;
                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
            END IF;

            IF v_qty IS NULL OR v_qty <= 0 THEN
                RAISE EXCEPTION 'Container ja vazio — nada para dar saida';
            END IF;

            SELECT COALESCE(quantidade_atual, 0)
              INTO v_saldo_anterior
              FROM estoque
             WHERE produto_master_id = v_pid
               AND loja_id = p_loja_id;

            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);

            IF p_tipo = 'entrada' THEN
                v_saldo_novo := v_saldo_anterior + v_qty;
            ELSE
                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
            END IF;

            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
                || ' · Lote ' || COALESCE(v_lote, '—');

            INSERT INTO movimentacoes (
                produto_master_id, tipo_movimentacao, quantidade,
                quantidade_anterior, quantidade_nova, motivo, observacoes,
                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
            ) VALUES (
                v_pid, p_tipo, v_qty,
                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
            );

            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
            v_ok := v_ok + 1;

        EXCEPTION WHEN OTHERS THEN
            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
            v_err := v_err + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', true,
        'processados', v_ok,
        'falhas', v_err,
        'resultados', v_resultados
    );
END;
$$;

-- Fecha o gap: a SAÍDA do scanner (saida_inteira) e os ajustes avulsos
-- (retirada_avulsa / adicao_avulsa) tambem precisam sincronizar estoque_lotes.
-- Antes so 'scanner_lote' (entrada) sincronizava -> estoque_lotes drifava pra cima
-- nas saidas, e o reconciliador reinflava o estoque agregado (entrada fantasma).
-- Verificado: nenhum desses fluxos faz UPDATE direto em estoque_lotes, entao
-- reagir a movimentacao aqui NAO causa dupla contagem.
CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(NEW.motivo,'') NOT IN (
       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa'
     ) THEN
    RETURN NEW;
  END IF;

  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
  PERFORM set_config('app.skip_lote_reconcile', '1', true);

  IF NEW.tipo_movimentacao = 'entrada' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;

  ELSIF NEW.tipo_movimentacao = 'saida' THEN
    UPDATE public.estoque_lotes
       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
     WHERE lote_id = NEW.lote_id
       AND produto_id = NEW.produto_master_id
       AND loja_id = NEW.loja_id;
  END IF;

  -- Sem linha pra esse (lote, produto, loja) e e entrada -> cria com a loja correta.
  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
  END IF;

  RETURN NEW;
END;
$function$;

-- Adicionar campo setor na tabela produtos
ALTER TABLE produtos ADD COLUMN setor character varying;

-- Atualizar produtos existentes para serem da câmara fria
UPDATE produtos SET setor = 'camara-fria' WHERE setor IS NULL;

-- Tornar o campo setor obrigatório
ALTER TABLE produtos ALTER COLUMN setor SET NOT NULL;

-- Adicionar campo para armazenar URL da foto
ALTER TABLE produtos ADD COLUMN foto_url character varying;

-- Criar bucket para fotos dos produtos
INSERT INTO storage.buckets (id, name, public) VALUES ('produto-fotos', 'produto-fotos', true);

-- Criar políticas RLS para o bucket de fotos dos produtos
CREATE POLICY "Qualquer um pode ver fotos de produtos" 
ON storage.objects 
