-- 1. Add produto_master_id to alertas_estoque
ALTER TABLE alertas_estoque 
ADD COLUMN IF NOT EXISTS produto_master_id INTEGER REFERENCES produtos_master(id);

-- 2. Update Function to handle both old (produto_id) and new (produto_master_id) logic
CREATE OR REPLACE FUNCTION atualizar_estoque_e_alertas() RETURNS TRIGGER AS $$
DECLARE
    estoque_atual DECIMAL(10,3);
    estoque_minimo DECIMAL(10,3);
BEGIN
    -- Scenario 1: New System (Master ID)
    IF NEW.produto_master_id IS NOT NULL THEN
        -- Upsert into estoque using (produto_master_id, loja_id)
        -- We assume 'estoque_produto_master_loja_unique' constraint exists on (produto_master_id, loja_id)
        INSERT INTO estoque (produto_master_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
        VALUES (NEW.produto_master_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
        ON CONFLICT (produto_master_id, loja_id) 
        DO UPDATE SET 
            quantidade_atual = EXCLUDED.quantidade_atual,
            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
            updated_at = NOW();

        -- Check Alerts
        SELECT quantidade_atual, quantidade_minima 
        INTO estoque_atual, estoque_minimo
        FROM estoque 
        WHERE produto_master_id = NEW.produto_master_id AND loja_id = NEW.loja_id;

        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
            IF estoque_atual <= 0 THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'critico', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= estoque_minimo THEN
                INSERT INTO alertas_estoque (produto_master_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_master_id, NEW.loja_id, 'baixo', estoque_atual, estoque_minimo);
            END IF;
        END IF;

    -- Scenario 2: Legacy System (Product ID)
    ELSIF NEW.produto_id IS NOT NULL THEN
        -- Upsert into estoque using (produto_id, loja_id)
        INSERT INTO estoque (produto_id, quantidade_atual, ultima_movimentacao, ultimo_usuario_id, loja_id)
        VALUES (NEW.produto_id, NEW.quantidade_nova, NEW.data_movimentacao, NEW.usuario_id, NEW.loja_id)
        ON CONFLICT (produto_id, loja_id) 
        DO UPDATE SET 
            quantidade_atual = EXCLUDED.quantidade_atual,
            ultima_movimentacao = EXCLUDED.ultima_movimentacao,
            ultimo_usuario_id = EXCLUDED.ultimo_usuario_id,
            updated_at = NOW();

        -- Check Alerts
        SELECT quantidade_atual, quantidade_minima 
        INTO estoque_atual, estoque_minimo
        FROM estoque 
        WHERE produto_id = NEW.produto_id AND loja_id = NEW.loja_id;

        IF estoque_atual IS NOT NULL AND estoque_minimo IS NOT NULL THEN
             IF estoque_atual <= 0 THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'sem_estoque', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= (estoque_minimo * 0.5) THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'critico', estoque_atual, estoque_minimo);
            ELSIF estoque_atual <= estoque_minimo THEN
                INSERT INTO alertas_estoque (produto_id, loja_id, tipo_alerta, quantidade_atual, quantidade_minima)
                VALUES (NEW.produto_id, NEW.loja_id, 'baixo', estoque_atual, estoque_minimo);
            END IF;
        END IF;

    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

