1	-- =============================================================================
2	-- Gidape ERP — COMMENT ON TABLE / COMMENT ON COLUMN (pt-BR)
3	-- Tabelas que já possuíam comentário foram omitidas. Strings com '' escapadas.
4	-- =============================================================================
5	
6	-- ============================== TABELAS ======================================
7	
8	-- núcleo / multi-loja
9	COMMENT ON TABLE public.lojas IS 'Cadastro das lojas/unidades (multi-loja). 1=Fábrica,2=Asa Sul,3=Asa Norte,4=Lago Sul,5=Águas Claras,6=Brasília Shopping.';
10	
11	-- estoque & movimentações
12	COMMENT ON TABLE public.categorias IS 'Categorias de produtos (com emoji e setor), usadas para classificar produtos e produtos_master por loja.';
13	COMMENT ON TABLE public.produtos IS 'Catálogo legado de produtos por loja (modelo antigo). Substituído gradualmente por produtos_master + produto_loja_visibility.';
14	COMMENT ON TABLE public.produtos_master IS 'Catálogo mestre unificado de produtos (source of truth). codigo_interno é a chave de negócio; ativo=true define produtos válidos.';
15	COMMENT ON TABLE public.estoque IS 'Saldo atual de estoque por produto e por loja, com mínimo/máximo para alertas. 1 linha por produto_master_id x loja_id.';
16	COMMENT ON TABLE public.movimentacoes IS 'Razão de todas as movimentações de estoque (entradas, saídas, ajustes, perdas). Log append-only que alimenta saldos e auditoria.';
17	COMMENT ON TABLE public.movimentacao_anexos IS 'Anexos (comprovantes/documentos) vinculados a uma movimentação de estoque.';
18	COMMENT ON TABLE public.alertas_estoque IS 'Alertas gerados quando estoque cruza mínimo/máximo (ex.: estoque baixo, ruptura). Marcados como resolvidos ao normalizar.';
19	COMMENT ON TABLE public.setores IS 'Setores operacionais (ex.: produção, confeitaria) usados para classificar produtos, categorias e etapas.';
20	COMMENT ON TABLE public.lotes IS 'Lotes de produto com código, validade e fabricação. Base da rastreabilidade por validade (shelf-life curto, doces saudáveis).';
21	COMMENT ON TABLE public.estoque_lotes IS 'Saldo de estoque por lote e por loja (quanto resta de cada lote em cada unidade).';
22	COMMENT ON TABLE public.perdas IS 'Registro de perdas/quebras de produto (motivo, valor estimado, foto), com fluxo de verificação. Multi-loja.';
23	COMMENT ON TABLE public.perdas_produtos IS 'Lista de produtos elegíveis para registro de perdas (catálogo auxiliar da tela de Perdas).';
24	COMMENT ON TABLE public.produto_loja_visibility IS 'Define quais produtos_master estão visíveis/ativos em cada loja. Sem linha ativa o produto some da busca da loja.';
25	COMMENT ON TABLE public.produto_legacy_mapping IS 'Mapeamento de produtos legados (produtos.id antigo) para o respectivo produto_master_id, por loja.';
26	COMMENT ON TABLE public.produto_sales_mapping IS 'Mapeia nomes/códigos de produto do PDV/vendas para produto_master_id, com status de conferência do match.';
27	COMMENT ON TABLE public.produto_aliases IS 'Apelidos/sinônimos de produtos aprendidos pelo matcher da requisição manual (fuzzy match), com contador de uso.';
28	COMMENT ON TABLE public.historico_vendas IS 'Histórico diário de vendas por produto e loja (qtd, valor, dia da semana). Base para forecast/DRP.';
29	COMMENT ON TABLE public.ncm_produtos IS 'Cadastro de NCM (classificação fiscal) e custo por produto/loja, usado em notas e tributação.';
30	COMMENT ON TABLE public.pronta_entrega_stock IS 'Estoque de pronta-entrega exposto na loja (produto, quantidade, validade, localização) para venda imediata.';
31	COMMENT ON TABLE public.pronta_entrega_logs IS 'Log de ações na pronta-entrega (entradas, baixas, ajustes) por usuário e loja.';
32	
33	-- requisições (lojas pedem à fábrica) & separação
34	COMMENT ON TABLE public.requisicoes IS 'Requisições de mercadoria que as lojas fazem à fábrica (cabeçalho: solicitante, preparador, lojas, datas, status, pipeline).';
35	COMMENT ON TABLE public.requisicoes_itens IS 'Itens de uma requisição (produto, qtd solicitada/enviada/recebida, separação, lote, validade).';
36	COMMENT ON TABLE public.requisition_pipelines IS 'Pipeline (workflow) de execução de uma requisição com etapas e coordenador. Fluxo estruturado de separação.';
37	COMMENT ON TABLE public.pipeline_funcionarios IS 'Funcionários alocados a cada etapa de um requisition_pipeline (papel e etapa atual).';
38	COMMENT ON TABLE public.pipeline_etapa_logs IS 'Log de ações/transições por etapa do requisition_pipeline (auditoria do workflow de separação).';
39	COMMENT ON TABLE public.pipeline_separacao_itens IS 'Itens separados por colaborador dentro de uma etapa do requisition_pipeline (qtd separada, status).';
40	COMMENT ON TABLE public.active_sessions IS 'Sessões de separação digital colaborativa em tempo real (cabeçalho: lojas, datas, status, expiração).';
41	COMMENT ON TABLE public.active_session_items IS 'Itens de uma sessão de separação digital (qtd solicitada/enviada, separado, bip de etiqueta QR).';
42	COMMENT ON TABLE public.active_review_sessions IS '(?) Sessões de conferência/revisão de separação ativas (cabeçalho temporário com expiração).';
43	COMMENT ON TABLE public.digital_separations IS 'Separações digitais (registro consolidado de uma sessão de separação concluída).';
44	COMMENT ON TABLE public.digital_separation_items IS 'Itens de uma separação digital (snapshot dos itens separados a partir da sessão).';
45	COMMENT ON TABLE public.digital_separation_users IS 'Usuários participando de uma separação digital colaborativa (presença em tempo real, cor de identificação).';
46	COMMENT ON TABLE public.expedicoes IS 'Expedições/rotas de entrega (Torre de Controle): agendamento, veículo, motorista, status.';
47	COMMENT ON TABLE public.expedicao_logs IS 'Log de eventos de uma expedição (saída, parada, entrega) vinculado a requisições. Timeline da Torre de Controle.';
48	
49	-- produção diária & PCP
50	COMMENT ON TABLE public.daily_production IS 'Produção diária registrada (produto, quantidade, data). loja_id NULL = fábrica (produção centralizada).';
51	COMMENT ON TABLE public.daily_production_products IS 'Produtos elegíveis para registro de produção diária por loja (lista da tela de produção).';
52	COMMENT ON TABLE public.daily_production_exclusions IS 'Produtos excluídos da lista de produção diária de uma loja.';
53	COMMENT ON TABLE public.weekly_production_plan IS 'Plano semanal de produção por loja/produto: demanda calculada, ajuste manual e produção final.';
54	COMMENT ON TABLE public.insumos IS 'Insumos/matérias-primas para produção: unidades de compra/produção, fatores de conversão e correção, custo, alérgenos.';
55	COMMENT ON TABLE public.fichas_tecnicas IS 'Fichas técnicas (receitas/BOM) de produtos: versão, rendimento, fator de rendimento, custo calculado.';
56	COMMENT ON TABLE public.ficha_tecnica_itens IS 'Itens de uma ficha técnica: insumo, sub-ficha (semi-acabado) ou produto, com quantidade, unidade e custo.';
57	COMMENT ON TABLE public.ficha_tecnica_etapas IS 'Etapas do processo produtivo de uma ficha técnica (ordem, setor, duração, temperatura, instruções).';
58	COMMENT ON TABLE public.ordens_producao IS 'Ordens de produção (OP): quantidades planejada/produzida/perdida, custos previsto/real, variância, lote e validade.';
59	COMMENT ON TABLE public.op_insumos IS 'Consumo de insumos por ordem de produção (qtd prevista x consumida, custo unitário e total).';
60	COMMENT ON TABLE public.op_perdas IS 'Perdas registradas por etapa dentro de uma ordem de produção (categoria, quantidade).';
61	COMMENT ON TABLE public.recipe_canvas_positions IS 'Posições (x,y) dos nós no canvas visual do construtor de fichas técnicas, por workspace.';
62	
63	-- encomendas & eventos
64	COMMENT ON TABLE public.encomendas IS 'Encomendas de clientes (delivery/retirada) com cliente, itens, entrega, pagamento e recorrência. Pode ter origem na Noaa.';
65	COMMENT ON TABLE public.eventos IS 'Eventos comerciais (feiras, ações externas) com data, local, responsável, faturamento e recorrência.';
66	COMMENT ON TABLE public.eventos_produtos IS 'Produtos enviados/separados para um evento (qtd enviada, retorno, perda, verificação).';
67	COMMENT ON TABLE public.eventos_custos IS 'Custos lançados em um evento (descrição, valor, tipo, anexo).';
68	COMMENT ON TABLE public.eventos_anexos IS 'Anexos/arquivos vinculados a um evento.';
69	COMMENT ON TABLE public.eventos_transacoes IS 'Transações financeiras (receitas/despesas) de um evento com categoria e comprovante.';
70	COMMENT ON TABLE public.eventos_perdas IS 'Perdas de produto registradas em um evento (produto, quantidade, motivo).';
71	COMMENT ON TABLE public.eventos_esocial IS 'Eventos eSocial gerados para um funcionário (XML, status de transmissão, resposta). Módulo RH.';
72	COMMENT ON TABLE public.orcamentos_gerados IS 'Orçamentos gerados para clientes (itens em JSON, valor total, desconto).';
73	COMMENT ON TABLE public.event_changelogs IS 'Changelog/auditoria de alterações em entidades de eventos e encomendas (ação, descrição, detalhes, autor).';
74	COMMENT ON TABLE public.acoes_marketing IS 'Ações de marketing com saída de produtos (degustação, cupom, embaixador, brinde, ação promocional etc.), com valor estimado e verificação.';
75	
76	-- logística (calendários/agenda)
77	COMMENT ON TABLE public.logistica_events IS '(?) Eventos de agenda logística simples (título, janela de tempo, loja). Provável modelo antigo de calendário.';
78	COMMENT ON TABLE public.logistica_calendarios IS 'Calendários da agenda de logística (nome, cor, padrão).';
79	COMMENT ON TABLE public.logistica_eventos IS 'Eventos da agenda de logística vinculados a um calendário (início/fim, dia inteiro, local).';
80	
81	-- financeiro: contas, cofre/livro caixa, NF, conciliação
82	COMMENT ON TABLE public.contas_pagar_receber IS 'Contas a pagar e a receber (tipo=pagar/receber), com vencimento, pagamento, parcelas, origem e vínculo a NF/fornecedor/conta bancária.';
83	COMMENT ON TABLE public.contas_pagar_receber_parcelas IS 'Parcelas de uma conta a pagar/receber (número, valor, vencimento, pagamento, juros, conta bancária).';
84	COMMENT ON TABLE public.movimentacoes_financeiras IS 'Lançamentos do Livro Caixa / Cofre por loja (entrada/saída), com categoria, forma de pagamento e responsável.';
85	COMMENT ON TABLE public.cofre_transferencias IS 'Transferências de valores entre cofres de lojas, ligando a movimentação de saída e a de entrada geradas.';
86	COMMENT ON TABLE public.custos_fixos IS 'Custos fixos mensais por loja, agrupados (grupo/item) e referenciados ao mês de competência.';
87	COMMENT ON TABLE public.notas_fiscais IS 'Notas fiscais de compra/entrada (fornecedor, valor, vencimento, forma de pagamento), com imagem para OCR. is_esboco=rascunho.';
88	COMMENT ON TABLE public.itens_nota_fiscal IS 'Itens de uma nota fiscal (produto, quantidade, valor unitário, subtotal), podendo vincular insumo.';
89	COMMENT ON TABLE public.notas_transferencia IS 'Notas de transferência entre lojas (ex.: Momma Doces). NÃO é nota fiscal/financeiro — apenas movimentação de mercadoria.';
90	COMMENT ON TABLE public.itens_nota_transferencia IS 'Itens de uma nota de transferência entre lojas (produto, quantidade, valor unitário, subtotal).';
91	COMMENT ON TABLE public.bank_accounts IS 'Contas bancárias por loja (banco, agência, conta, saldo inicial/atual) para conciliação financeira.';
92	COMMENT ON TABLE public.bank_transactions IS 'Transações bancárias (extrato), em geral importadas de OFX. Marcadas como conciliadas ao casar com lançamentos.';
93	COMMENT ON TABLE public.ofx_imports IS 'Importações de arquivos OFX de extrato bancário (período, contagem, totais de crédito/débito).';
94	COMMENT ON TABLE public.credit_cards IS 'Cartões de crédito por loja (bandeira, limite, dias de fechamento/vencimento).';
